            for component_id, solver in SOLVERS.items()}

import heapq
import itertools


def _temporal(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    visit_bits = {}
    for i, node in enumerate(required):
        visit_bits[node] = visit_bits.get(node, 0) | (1 << i)

    source = data["source"]
    initial_mask = visit_bits.get(source, 0)
    remaining = data["coupons"]
    start = data["start"]
    initial = (source, initial_mask, remaining)
    best = {initial: start}
    queue = [(start, source, initial_mask, remaining)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if best.get(state) != time:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule == "at_most" or left == 0)):
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], left)]
            if left:
                discounted = max(minimum_duration,
                                 edge["duration"] - edge.get("discount", 0))
                durations.append((discounted, left - 1))
            for duration, next_left in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | visit_bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_left)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue,
                                   (arrival, next_node, next_mask, next_left))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator, denominator=10000):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    rows_by_name = {}
    for name in names:
        rows = {row["version"]: row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])}
        rows_by_name[name] = rows
        choices.append([-1] + sorted(rows))

    best_vector = None
    best_versions = None
    for vector in itertools.product(*choices):
        versions = dict(zip(names, vector))
        valid = True
        for name, bounds in data["roots"].items():
            version = versions.get(name, -1)
            if version < 0 or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        edges = {}
        reachable = set()
        pending = list(data["roots"])
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            version = versions.get(name, -1)
            if version < 0:
                valid = False
                break
            row = rows_by_name[name][version]
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = versions.get(target, -1)
                if (target_version < 0 or not dep["min"] <= target_version
                        <= dep["max"]):
                    valid = False
                    break
                active.append(target)
                if target not in reachable:
                    pending.append(target)
            edges[name] = active

        if not valid or any(v >= 0 and name not in reachable
                            for name, v in versions.items()):
            continue

        finished = set()
        active_path = set()

        def acyclic(name):
            if name in active_path:
                return False
            if name in finished:
                return True
            active_path.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            active_path.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in reachable):
            continue

        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_versions = {name: version for name, version in versions.items()
                             if version >= 0}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quotas(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    options = [job for job in jobs if job["id"] not in blocked]
    k = data["k"]
    if len(mandatory) > k or not mandatory.issubset(
            {job["id"] for job in options}):
        return {"error": "impossible"}

    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for selected in itertools.combinations(options, k):
        ids = sorted(job["id"] for job in selected)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": lambda data: _temporal(data, "at_most", 2),
    "component_02": lambda data: _temporal(data, "exact", 2),
    "component_03": lambda data: _temporal(data, "at_most", 1),
    "component_04": lambda data: _temporal(data, "exact", 1),
    "component_05": lambda data: _temporal(data, "at_most", 2),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _quotas,
}
